27	export default function OrderScreen({
28	  qrSlug,
29	  businessName,
30	  tableName,
31	  products,
32	}: {
33	  qrSlug: string;
34	  businessName: string;
35	  tableName: string;
36	  products: Product[];
37	}) {
38	  const [cart, setCart] = useState<CartItem[]>([]);
39	  const [submitting, setSubmitting] = useState(false);
40	  const [error, setError] = useState<string | null>(null);
41	  const [sent, setSent] = useState(false);
42	
43	  const categories = useMemo(() => {
44	    const set = new Set<string>();
45	    for (const p of products) set.add(p.category || "Lainnya");
46	    return Array.from(set);
47	  }, [products]);
48	
49	  const total = cart.reduce((sum, i) => sum + i.price * i.qty, 0);
50	  const itemCount = cart.reduce((sum, i) => sum + i.qty, 0);
51	
52	  function changeQty(product: Product, delta: number) {
53	    setCart((prev) => {
54	      const existing = prev.find((i) => i.productId === product.id);
55	      if (!existing) {
56	        if (delta <= 0) return prev;
57	        return [
58	          ...prev,
59	          { productId: product.id, name: product.name, price: product.price, qty: 1, note: "" },
60	        ];
61	      }
62	      const qty = Math.min(99, Math.max(0, existing.qty + delta));
63	      if (qty === 0) return prev.filter((i) => i.productId !== product.id);
64	      return prev.map((i) => (i.productId === product.id ? { ...i, qty } : i));
65	    });
66	  }
67	
68	  function setNote(productId: string, note: string) {
69	    setCart((prev) => prev.map((i) => (i.productId === productId ? { ...i, note } : i)));
70	  }
71	
72	  async function handleSubmit() {
73	    setError(null);
74	    setSubmitting(true);
75	    const result = await submitSelfOrder(
76	      qrSlug,
77	      cart.map((i) => ({
78	        productId: i.productId,
79	        qty: i.qty,
80	        note: i.note.trim() || null,
81	      })),
82	    );
83	    setSubmitting(false);
84	
85	    if (!result.success) {
86	      setError(result.error);
87	      return;
88	    }
89	
90	    setSent(true);
91	    setCart([]);
92	  }
93	
94	  if (sent) {
95	    return (
96	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
