102	          <p className="mt-1 text-sm text-zinc-500">
103	            Pesanan untuk {tableName} sudah diterima. Silakan lakukan pembayaran di kasir.
104	          </p>
105	          <button
106	            onClick={() => setSent(false)}
107	            className="mt-6 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
108	          >
109	            Pesan Lagi
110	          </button>
111	        </div>
112	      </div>
113	    );
114	  }
115	
116	  return (
117	    <div className="flex flex-1 flex-col items-center bg-zinc-50 px-4 py-8 pb-28">
118	      <div className="w-full max-w-sm">
119	        <p className="text-xs font-medium text-zinc-400">{businessName}</p>
120	        <h1 className="text-lg font-bold text-zinc-900">🪑 {tableName}</h1>
121	        <p className="mt-1 text-sm text-zinc-500">
122	          Pilih menu, lalu kirim pesanan. Pembayaran dilakukan di kasir.
123	        </p>
124	
125	        {products.length === 0 ? (
126	          <p className="mt-8 rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
127	            Menu belum tersedia.
128	          </p>
129	        ) : (
130	          categories.map((cat) => (
131	            <div key={cat} className="mt-6">
132	              <h2 className="mb-2 text-xs font-semibold uppercase tracking-wide text-zinc-400">
133	                {cat}
134	              </h2>
135	              <div className="space-y-2">
136	                {products
137	                  .filter((p) => (p.category || "Lainnya") === cat)
138	                  .map((p) => {
139	                    const inCart = cart.find((i) => i.productId === p.id);
140	                    return (
141	                      <div
142	                        key={p.id}
143	                        className={`rounded-xl border bg-white p-3 ${
144	                          inCart ? "border-brand-300" : "border-zinc-200"
145	                        } ${p.in_stock ? "" : "opacity-50"}`}
146	                      >
147	                        <div className="flex items-center gap-3">
148	                          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-zinc-100 text-xl">
149	                            {p.emoji || "🍽️"}
150	                          </div>
151	                          <div className="min-w-0 flex-1">
152	                            <p className="truncate text-sm font-medium text-zinc-900">{p.name}</p>
153	                            <p className="text-xs text-zinc-500">
154	                              {p.in_stock ? formatRupiah(p.price) : "Habis"}
155	                            </p>
156	                          </div>
157	                          {p.in_stock && (
158	                            <div className="flex shrink-0 items-center gap-2">
159	                              {inCart && (
160	                                <>
161	                                  <button
162	                                    onClick={() => changeQty(p, -1)}
163	                                    className="flex h-7 w-7 items-center justify-center rounded-md bg-zinc-100 text-sm font-bold text-zinc-600 hover:bg-zinc-200"
164	                                  >
165	                                    −
166	                                  </button>
167	                                  <span className="w-4 text-center text-sm tabular-nums">
168	                                    {inCart.qty}
169	                                  </span>
170	                                </>
171	                              )}
172	                              <button
173	                                onClick={() => changeQty(p, 1)}
174	                                className="flex h-7 w-7 items-center justify-center rounded-md bg-brand-600 text-sm font-bold text-white hover:bg-brand-700"
175	                              >
176	                                +
177	                              </button>
178	                            </div>
179	                          )}
180	                        </div>
181	                        {inCart && (
182	                          <input
183	                            type="text"
184	                            value={inCart.note}
185	                            onChange={(e) => setNote(p.id, e.target.value)}
186	                            maxLength={200}
187	                            placeholder="Catatan (mis. tanpa es, pedas)…"
188	                            className="mt-2 w-full rounded-lg border border-zinc-200 px-3 py-1.5 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
189	                          />
190	                        )}
191	                      </div>
192	                    );
193	                  })}
194	              </div>
195	            </div>
196	          ))
197	        )}
198	      </div>
199	
200	      {/* Sticky submit bar */}
201	      {cart.length > 0 && (
202	        <div className="fixed inset-x-0 bottom-0 border-t border-zinc-200 bg-white px-4 py-3">
203	          <div className="mx-auto w-full max-w-sm">
204	            {error && (
205	              <p className="mb-2 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
206	            )}
207	            <button
208	              onClick={handleSubmit}
209	              disabled={submitting}
210	              className="flex w-full items-center justify-between rounded-xl bg-brand-600 px-4 py-3 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
211	            >
212	              <span>{submitting ? "Mengirim…" : `Kirim Pesanan (${itemCount} item)`}</span>
213	              <span>{formatRupiah(total)}</span>
214	            </button>
215	          </div>
216	        </div>
217	      )}
218	    </div>
219	  );
220	}
