5	export type SubmitOrderResult =
6	  | { success: true }
7	  | { success: false; error: string };
8	
9	export async function submitSelfOrder(
10	  qrSlug: string,
11	  items: { productId: string; qty: number; note: string | null }[],
12	): Promise<SubmitOrderResult> {
13	  if (items.length === 0) {
14	    return { success: false, error: "Keranjang masih kosong." };
15	  }
16	
17	  const supabase = await createClient();
18	  const { error } = await supabase.rpc("submit_self_order", {
19	    p_qr_slug: qrSlug,
20	    p_items: items.map((i) => ({
21	      product_id: i.productId,
22	      qty: i.qty,
23	      note: i.note,
24	    })),
25	  });
26	
27	  if (error) {
28	    return { success: false, error: "Pesanan gagal terkirim. Coba lagi." };
29	  }
30	
31	  return { success: true };
32	}
