1	-- Module 8: checkout as a single atomic RPC. Everything (transaction row,
2	-- line items, payment row, stock decrement) happens in one Postgres
3	-- function call, so a failure partway through rolls back everything instead
4	-- of leaving an orphaned transaction. Price/cost/name/category are always
5	-- looked up from public.products server-side — never trusted from the
6	-- client — so a tampered request can't check out at a fake price.
7	
8	create or replace function public.checkout_transaction(
9	  p_business_id uuid,
10	  p_cashier_id uuid,
11	  p_items jsonb, -- array of {product_id, qty}
12	  p_payment_method text,
13	  p_received numeric default null
14	)
15	returns table (transaction_id uuid, invoice_number text)
16	language plpgsql
17	security definer
18	set search_path = ''
19	as $$
20	declare
21	  v_invoice_number text;
22	  v_seq int;
23	  v_subtotal numeric(12, 2) := 0;
24	  v_total_cost numeric(12, 2) := 0;
25	  v_transaction_id uuid;
26	  v_item jsonb;
27	  v_qty numeric(12, 2);
28	  v_product_id uuid;
29	  v_product record;
30	  v_change numeric(12, 2);
31	begin
32	  if not private.owns_business(p_business_id) then
33	    raise exception 'not authorized';
34	  end if;
35	
36	  if not exists (
37	    select 1 from public.cashiers c
38	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
39	  ) then
40	    raise exception 'invalid cashier';
41	  end if;
42	
43	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
44	    raise exception 'payment method required';
45	  end if;
46	
47	  if p_items is null or jsonb_array_length(p_items) = 0 then
48	    raise exception 'cart is empty';
49	  end if;
50	
51	  select count(*) + 1 into v_seq
52	  from public.transactions t
53	  where t.business_id = p_business_id
54	    and t.date::date = current_date;
55	
56	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
57	
58	  insert into public.transactions (
59	    business_id, cashier_id, invoice_number, date,
60	    subtotal_raw, subtotal, total, total_cost, gross_profit
61	  ) values (
62	    p_business_id, p_cashier_id, v_invoice_number, now(),
63	    0, 0, 0, 0, 0
64	  )
65	  returning id into v_transaction_id;
66	
67	  for v_item in select * from jsonb_array_elements(p_items)
68	  loop
69	    v_product_id := (v_item ->> 'product_id')::uuid;
70	    v_qty := (v_item ->> 'qty')::numeric;
71	
72	    if v_qty is null or v_qty <= 0 then
73	      raise exception 'invalid quantity';
74	    end if;
75	
76	    select * into v_product
77	    from public.products p
78	    where p.id = v_product_id
79	      and p.business_id = p_business_id
80	      and p.deleted_at is null;
81	
82	    if not found then
83	      raise exception 'product not found: %', v_product_id;
84	    end if;
85	
86	    insert into public.transaction_items (
87	      transaction_id, product_id, name, category, price, cost, qty
88	    ) values (
89	      v_transaction_id, v_product.id, v_product.name, v_product.category,
90	      v_product.price, v_product.cost, v_qty
91	    );
92	
93	    update public.products
94	    set stock = greatest(0, stock - v_qty)
95	    where id = v_product_id;
96	
97	    v_subtotal := v_subtotal + v_product.price * v_qty;
98	    v_total_cost := v_total_cost + v_product.cost * v_qty;
99	  end loop;
100	
101	  update public.transactions
102	  set subtotal_raw = v_subtotal,
103	      subtotal = v_subtotal,
104	      total = v_subtotal,
105	      total_cost = v_total_cost,
106	      gross_profit = v_subtotal - v_total_cost
107	  where id = v_transaction_id;
108	
109	  v_change := greatest(coalesce(p_received, v_subtotal) - v_subtotal, 0);
110	
111	  insert into public.transaction_payments (
112	    transaction_id, method, amount, received, change
113	  ) values (
114	    v_transaction_id, p_payment_method, v_subtotal, p_received, v_change
115	  );
116	
117	  return query select v_transaction_id, v_invoice_number;
118	end;
119	$$;
