16	
17	  if (!name) {
18	    return { error: "Nama meja wajib diisi." };
19	  }
20	
21	  const supabase = await createClient();
22	  const { error } = await supabase.from("tables").insert({
23	    business_id: businessId,
24	    name,
25	    qr_slug: randomBytes(9).toString("base64url"),
26	  });
27	
28	  if (error) {
29	    return { error: error.message };
30	  }
31	
32	  await logActivity(supabase, businessId, "pengaturan", "sukses", `Meja baru: ${name}`);
33	  revalidatePath(`/business/${businessId}/tables`);
34	  return { error: null };
35	}
